1	/**
2	 * POST /functions/v1/ask — the assistant behind the Ask tab.
3	 *
4	 * Deno. This file is deliberately not in `tsconfig.json`'s include list: it
5	 * needs `Deno.env` and npm: specifiers, neither of which the app's TypeScript
6	 * config knows about. Everything that can be tested without a network lives in
7	 * `./lib.ts`, which is typechecked and unit tested.
8	 *
9	 * The order of operations matters and is the same on every request:
10	 *
11	 *   1. CORS, method, body.
12	 *   2. JWT. No valid bearer token, no answer — the catalogue is public but the
13	 *      model is not, and an unauthenticated function is a bill with a URL.
14	 *   3. Rate limit, from `ask_usage`. Counted before the model is called and
15	 *      before the fixtures are read, so the stub hits the same ceiling the live
16	 *      path does.
17	 *   4. Scope. Peptide and pregnancy questions are refused here, by the server,
18	 *      with fixed wording — before the model sees them. A rule in the system
19	 *      prompt can be argued with; this cannot.
20	 *   5. The answer. With no ANTHROPIC_API_KEY set it comes from `./fixtures.ts`.
21	 *      With one set it comes from Claude. Setting the key is the only
22	 *      difference between the two paths.
23	 *
24	 * SECRETS. `ANTHROPIC_API_KEY` is read from the environment and is absent by
25	 * design. It is never logged, never returned, and never reaches the client —
26	 * the client only ever learns whether an answer was stubbed. This function
27	 * runs on the caller's own JWT and the anon key, never the service role.
28	 *
29	 * DEPLOY: supabase functions deploy ask
30	 *         supabase secrets set ANTHROPIC_API_KEY=...   (only when going live)
31	 *         migration 0024 must be applied first, or every request 500s on the
32	 *         rate-limit read.
33	 */
34	
35	import { createClient } from 'npm:@supabase/supabase-js@2';
36	import Anthropic from 'npm:@anthropic-ai/sdk@0.117.1';
37	
38	import {
39	  buildCards,
40	  buildCatalogueBlock,
41	  buildDetail,
42	  buildProfileBlock,
43	  classifyScope,
44	  INSTRUCTIONS,
45	  MAX_TOKENS,
46	  MAX_TOOL_ROUNDS,
47	  MODEL,
48	  parseRequest,
49	  rateVerdict,
50	  readDetailSlugs,
51	  readShowProducts,
52	  TOOLS,
53	} from './lib.ts';
54	import type {
55	  AskAnswer,
56	  AskCard,
57	  AskCitation,
58	  AskErrorCode,
59	  AskRequest,
60	  AskUsage,
61	  CatalogueEntry,
62	  ProfileContext,
63	  RequestedCard,
64	} from './lib.ts';
65	import { ANSWER_FIXTURES, ERROR_FIXTURES, pickFixture } from './fixtures.ts';
66	
67	/** Opting into server-side refusal fallbacks; see callModel below. */
68	const FALLBACK_BETA = 'server-side-fallback-2026-07-01';
69	
70	const CORS: Record<string, string> = {
71	  'Access-Control-Allow-Origin': '*',
72	  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type',
73	  'Access-Control-Allow-Methods': 'POST, OPTIONS',
74	};
75	
76	function json(body: unknown, status = 200): Response {
77	  return new Response(JSON.stringify(body), {
78	    status,
79	    headers: { ...CORS, 'Content-Type': 'application/json' },
80	  });
81	}
82	
83	function fail(code: AskErrorCode, message: string, status: number, retryAfter?: number): Response {
84	  const body = { error: { code, message, ...(retryAfter ? { retry_after: retryAfter } : {}) } };
85	  return json(body, status);
86	}
87	
88	// ============================================================================
89	// Database reads
90	// ============================================================================
91	
92	const CATALOGUE_COLUMNS =
93	  'id,slug,name,brand,product_form,goal_tags,kind,timing,timing_note,evidence,mechanism_summary,label_url,ods_url';
94	
95	interface CatalogueRow extends CatalogueEntry {
96	  id: string;
97	}
98	
99	function toEntry(row: Record<string, unknown>): CatalogueRow {
100	  return {
101	    id: String(row.id),
102	    slug: String(row.slug),
103	    name: String(row.name),
104	    brand: (row.brand as string) ?? null,
105	    product_form: (row.product_form as string) ?? null,
106	    goal_tags: Array.isArray(row.goal_tags) ? (row.goal_tags as string[]) : [],
107	    kind: (row.kind as string) ?? null,
108	    timing: (row.timing as string) ?? null,
109	    timing_note: (row.timing_note as string) ?? null,
110	    evidence: (row.evidence as string) ?? null,
111	    mechanism_summary: (row.mechanism_summary as string) ?? null,
112	    label_url: (row.label_url as string) ?? null,
113	    ods_url: (row.ods_url as string) ?? null,
114	  };
115	}
116	
117	// ============================================================================
118	// Handler
119	// ============================================================================
120	
121	Deno.serve(async (req: Request): Promise<Response> => {
122	  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS });
123	  if (req.method !== 'POST') return fail('bad_request', 'Use POST.', 405);
124	
125	  const supabaseUrl = Deno.env.get('SUPABASE_URL');
126	  const anonKey = Deno.env.get('SUPABASE_ANON_KEY');
127	  if (!supabaseUrl || !anonKey) {
128	    console.error('ask: SUPABASE_URL or SUPABASE_ANON_KEY missing from the environment');
129	    return fail('server_error', ERROR_FIXTURES.server_error.body.error.message, 500);
130	  }
131	
132	  // ---- 1. body -------------------------------------------------------------
133	  let raw: unknown;
134	  try {
135	    raw = await req.json();
136	  } catch {
137	    return fail('bad_request', 'Send a JSON object with a question.', 400);
138	  }
139	  const parsed = parseRequest(raw);
140	  if (!parsed.ok) return fail('bad_request', parsed.message, 400);
141	  const request: AskRequest = parsed.value;
142	
143	  // ---- 2. JWT --------------------------------------------------------------
144	  const authHeader = req.headers.get('Authorization') ?? '';
145	  if (!authHeader.toLowerCase().startsWith('bearer ')) {
146	    return fail('unauthorized', 'Sign in to ask a question.', 401);
147	  }
148	  const supabase = createClient(supabaseUrl, anonKey, {
149	    global: { headers: { Authorization: authHeader } },
150	    auth: { persistSession: false, autoRefreshToken: false, detectSessionInUrl: false },
151	  });
152	  const { data: auth, error: authError } = await supabase.auth.getUser();
153	  const user = auth?.user;
154	  if (authError || !user) {
155	    return fail('unauthorized', 'That session has expired. Sign in again.', 401);
156	  }
157	
158	  try {
159	    // ---- 3. rate limit -----------------------------------------------------
160	    const now = Date.now();
161	    const since = new Date(now - 24 * 60 * 60 * 1000).toISOString();
162	    const { data: usageRows, error: usageError } = await supabase
163	      .from('ask_usage')
164	      .select('created_at')
165	      .eq('user_id', user.id)
166	      .gte('created_at', since);
167	    if (usageError) throw usageError;
168	
169	    const stamps = (usageRows ?? []).map((row: { created_at: string }) =>
170	      Date.parse(row.created_at),
171	    );
172	    const verdict = rateVerdict(now, stamps.filter((t: number) => Number.isFinite(t)));
173	    if (!verdict.allowed) {
174	      return fail(
175	        'rate_limited',
176	        ERROR_FIXTURES.rate_limit.body.error.message,
177	        429,
178	        verdict.retry_after,
179	      );
180	    }
181	
182	    const { error: insertError } = await supabase.from('ask_usage').insert({ user_id: user.id });
183	    if (insertError) throw insertError;
184	
185	    const usage: AskUsage = {
186	      remaining_hour: verdict.remaining_hour - 1,
187	      remaining_day: verdict.remaining_day - 1,
188	      resets_at: verdict.resets_at,
189	    };
190	
191	    // ---- catalogue ---------------------------------------------------------
192	    const { data: glossaryRows, error: glossaryError } = await supabase
193	      .from('glossary')
194	      .select(CATALOGUE_COLUMNS)
195	      .order('name');
196	    if (glossaryError) throw glossaryError;
197	
198	    const all = (glossaryRows ?? []).map(toEntry);
199	    const supplements = all.filter((row) => row.kind !== 'peptide');
200	    const peptideTerms = all
201	      .filter((row) => row.kind === 'peptide')
202	      .flatMap((row) => [row.name, row.slug]);
203	
204	    const bySlug = new Map<string, CatalogueRow>();
205	    for (const row of supplements) bySlug.set(row.slug, row);
206	
207	    // ---- 4. scope ----------------------------------------------------------
208	    const scope = classifyScope(request.question, peptideTerms);
209	    const hasKey = Boolean(Deno.env.get('ANTHROPIC_API_KEY'));
210	
211	    if (scope !== 'ok') {
212	      const fixture = ANSWER_FIXTURES[scope];
213	      const answer: AskAnswer = { answer: fixture.answer, cards: [], usage, stub: true };
214	      return json(answer);
215	    }
216	
217	    // ---- 5. answer ---------------------------------------------------------
218	    if (!hasKey) return await stubAnswer(supabase, request, bySlug, usage);
219	    return await liveAnswer(supabase, request, supplements, bySlug, user.id, usage);
220	  } catch (err) {
221	    // The message can carry a Postgres error or an upstream body; it stays in
222	    // the function log and never goes back to the client.
223	    console.error('ask: request failed', err);
224	    return fail('server_error', ERROR_FIXTURES.server_error.body.error.message, 500);
225	  }
226	});
227	
228	// ============================================================================
229	// Citations
230	// ============================================================================
231	
232	async function fetchCitations(
233	  supabase: ReturnType<typeof createClient>,
234	  entries: CatalogueRow[],
235	): Promise<Map<string, AskCitation[]>> {
236	  const out = new Map<string, AskCitation[]>();
237	  if (entries.length === 0) return out;
238	  const slugById = new Map(entries.map((e) => [e.id, e.slug]));
239	  const { data, error } = await supabase
240	    .from('glossary_research')
241	    .select('glossary_id,title,meta,url')
242	    .in('glossary_id', [...slugById.keys()]);
243	  if (error) throw error;
244	  for (const row of data ?? []) {
245	    const slug = slugById.get(String(row.glossary_id));
246	    if (!slug) continue;
247	    const list = out.get(slug) ?? [];
248	    list.push({
249	      title: String(row.title),
250	      meta: (row.meta as string) ?? null,
251	      url: (row.url as string) ?? null,
252	    });
253	    out.set(slug, list);
254	  }
255	  return out;
256	}
257	
258	// ============================================================================
259	// The stub path — no key
260	// ============================================================================
261	
262	async function stubAnswer(
263	  supabase: ReturnType<typeof createClient>,
264	  request: AskRequest,
265	  bySlug: Map<string, CatalogueRow>,
266	  usage: AskUsage,
267	): Promise<Response> {
268	  const key = pickFixture(request.question, 'ok');
269	  if (key === 'rate_limit' || key === 'server_error') {
270	    const fixture = ERROR_FIXTURES[key];
271	    return json(fixture.body, fixture.status);
272	  }
273	
274	  const fixture = ANSWER_FIXTURES[key];
275	  const wanted = fixture.cards.map((card) => card.slug);
276	  const present = wanted
277	    .map((slug) => bySlug.get(slug))
278	    .filter((row): row is CatalogueRow => row !== undefined);
279	
280	  const citations = await fetchCitations(supabase, present);
281	  // Fixture citations stand in for products the applied database does not hold
282	  // yet; a resolved product uses its own papers.
283	  for (const [slug, list] of Object.entries(fixture.citations)) {
284	    if (!citations.has(slug)) citations.set(slug, list);
285	  }
286	
287	  const fallback = new Map<string, CatalogueEntry>();
288	  for (const row of fixture.products) fallback.set(row.slug, row);
289	
290	  const cards = buildCards(fixture.cards, bySlug, citations, fallback);
291	  const answer: AskAnswer = { answer: fixture.answer, cards, usage, stub: true };
292	  return json(answer);
293	}
294	
295	// ============================================================================
296	// The live path — a key is set
297	// ============================================================================
298	
299	async function liveAnswer(
300	  supabase: ReturnType<typeof createClient>,
301	  request: AskRequest,
302	  supplements: CatalogueRow[],
303	  bySlug: Map<string, CatalogueRow>,
304	  userId: string,
305	  usage: AskUsage,
306	): Promise<Response> {
307	  const [profile, stackNames] = await Promise.all([
308	    loadProfile(supabase, userId),
309	    loadStackNames(supabase, userId),
310	  ]);
311	
312	  const client = new Anthropic({ apiKey: Deno.env.get('ANTHROPIC_API_KEY') });
313	
314	  const system = [
315	    { type: 'text', text: INSTRUCTIONS },
316	    // The catalogue is identical for every person, so the breakpoint goes here
317	    // and the whole prefix — tools included — is read back on the next request
318	    // rather than paid for again. Anything per-person goes in the user turn.
319	    {
320	      type: 'text',
321	      text: buildCatalogueBlock(supplements),
322	      cache_control: { type: 'ephemeral' },
323	    },
324	  ];
325	
326	  const opening = `${buildProfileBlock(profile, stackNames)}\n\n${request.question}`;
327	  const messages: { role: 'user' | 'assistant'; content: unknown }[] = [
328	    ...request.history.map((turn) => ({ role: turn.role, content: turn.text })),
329	    { role: 'user' as const, content: opening },
330	  ];
331	
332	  let requested: RequestedCard[] = [];
333	  let text = '';
334	
335	  for (let round = 0; round < MAX_TOOL_ROUNDS; round++) {
336	    const response = await callModel(client, {
337	      model: MODEL,
338	      max_tokens: MAX_TOKENS,
339	      output_config: { effort: 'medium' },
340	      system,
341	      tools: TOOLS,
342	      messages,
343	    });
344	
345	    if (response.stop_reason === 'refusal') {
346	      const answer: AskAnswer = {
347	        answer:
348	          'I cannot answer that one. If it is about something you are taking, ask it a different way and I will try again.',
349	        cards: [],
350	        usage,
351	        stub: false,
352	      };
353	      return json(answer);
354	    }
355	
356	    const blocks: { type: string; text?: string; name?: string; id?: string; input?: unknown }[] =
357	      response.content ?? [];
358	    const said = blocks
359	      .filter((block) => block.type === 'text')
360	      .map((block) => block.text ?? '')
361	      .join('\n')
362	      .trim();
363	    if (said) text = said;
364	
365	    const calls = blocks.filter((block) => block.type === 'tool_use');
366	    if (response.stop_reason !== 'tool_use' || calls.length === 0) break;
367	
368	    messages.push({ role: 'assistant', content: response.content });
369	    const results: unknown[] = [];
370	    for (const call of calls) {
371	      results.push({
372	        type: 'tool_result',
373	        tool_use_id: call.id,
374	        content: await runTool(supabase, call.name ?? '', call.input, bySlug, (cards) => {
375	          requested = cards;
376	        }),
377	      });
378	    }
379	    messages.push({ role: 'user', content: results });
380	  }
381	
382	  const present = requested
383	    .map((card) => bySlug.get(card.slug))
384	    .filter((row): row is CatalogueRow => row !== undefined);
385	  const citations = await fetchCitations(supabase, present);
386	  const cards: AskCard[] = buildCards(requested, bySlug, citations);
387	
388	  const answer: AskAnswer = {
389	    answer: text || 'I could not put an answer together for that. Try asking it a different way.',
390	    cards,
391	    usage,
392	    stub: false,
393	  };
394	  return json(answer);
395	}
396	
397	/**
398	 * One model call, with server-side refusal fallbacks turned on. A health
399	 * question can trip a safety classifier; with `fallbacks: 'default'` the API
400	 * re-runs it on Anthropic's recommended model inside the same call rather than
401	 * handing back a refusal.
402	 *
403	 * The retry exists because this repo ships with no key and cannot exercise
404	 * either path: if this deployment's API or SDK does not know that beta, the
405	 * question still gets answered instead of every request 400ing.
406	 */
407	// deno-lint-ignore no-explicit-any
408	async function callModel(client: any, params: Record<string, unknown>): Promise<any> {
409	  try {
410	    return await client.beta.messages.create({
411	      ...params,
412	      betas: [FALLBACK_BETA],
413	      fallbacks: 'default',
414	    });
415	  } catch (err) {
416	    const status = (err as { status?: number })?.status;
417	    const message = String((err as { message?: string })?.message ?? '');
418	    if (status !== 400 || !/fallback|beta/i.test(message)) throw err;
419	    console.error('ask: refusal fallbacks rejected, retrying without them —', message);
420	    return await client.beta.messages.create(params);
421	  }
422	}
423	
424	async function runTool(
425	  supabase: ReturnType<typeof createClient>,
426	  name: string,
427	  input: unknown,
428	  bySlug: Map<string, CatalogueRow>,
429	  onShow: (cards: RequestedCard[]) => void,
430	): Promise<string> {
431	  if (name === 'get_product_detail') {
432	    const slugs = readDetailSlugs(input);
433	    const found = slugs
434	      .map((slug) => bySlug.get(slug))
435	      .filter((row): row is CatalogueRow => row !== undefined);
436	    if (found.length === 0) return 'No catalogue entry matches those slugs.';
437	    const citations = await fetchCitations(supabase, found);
438	    return found.map((row) => buildDetail(row, citations.get(row.slug) ?? [])).join('\n\n');
439	  }
440	
441	  if (name === 'show_products') {
442	    const cards = readShowProducts(input);
443	    const known = cards.filter((card) => bySlug.has(card.slug));
444	    onShow(known);
445	    const dropped = cards.length - known.length;
446	    return dropped > 0
447	      ? `Showing ${known.length}. ${dropped} slug(s) are not in the catalogue and were dropped — do not mention them.`
448	      : `Showing ${known.length}.`;
449	  }
450	
451	  return `No tool named ${name}.`;
452	}
453	
454	async function loadProfile(
455	  supabase: ReturnType<typeof createClient>,
456	  userId: string,
457	): Promise<ProfileContext | null> {
458	  // `select('*')` rather than a column list: diet, reactions and the rest
459	  // arrive with migrations 0018 and 0019, and naming a column that has not
460	  // been added yet fails the whole request.
461	  const { data } = await supabase.from('profiles').select('*').eq('id', userId).maybeSingle();
462	  return (data as ProfileContext) ?? null;
463	}
464	
465	async function loadStackNames(
466	  supabase: ReturnType<typeof createClient>,
467	  userId: string,
468	): Promise<string[]> {
469	  const { data } = await supabase
470	    .from('schedule_items')
471	    .select('name')
472	    .eq('user_id', userId)
473	    .eq('active', true)
474	    .limit(25);
475	  return (data ?? []).map((row: { name: string }) => row.name);
476	}
