2	 * The pure half of the `ask` edge function: request validation, the scope
3	 * rules, the rate-limit arithmetic, prompt assembly, and turning what the
4	 * model asked for into cards the app can render.
5	 *
6	 * Nothing in here touches Deno, the network or the clock — `index.ts` owns all
7	 * three and passes in what it read. That split is the whole point: it lets
8	 * `tests/unit/ask.spec.ts` run this file in Node, and it is why this file is in
9	 * `tsconfig.json`'s include list while `index.ts`, which needs Deno globals,
10	 * is not.
11	 */
12	
13	// ============================================================================
14	// Limits and constants
15	// ============================================================================
16	
17	/** Claude Opus 5. Thinking is on by default on this model; we leave it on. */
18	export const MODEL = 'claude-opus-5';
19	
20	/** Room for adaptive thinking plus the answer, well under any HTTP timeout. */
21	export const MAX_TOKENS = 8192;
22	
23	/** Long enough for a real question, short enough that nobody pastes a book. */
24	export const MAX_QUESTION_CHARS = 600;
25	
26	/** Turns of prior conversation carried into the request, newest kept. */
27	export const MAX_HISTORY_TURNS = 12;
28	
29	/** The answer shows at most three products. More is a list, not an answer. */
30	export const MAX_CARDS = 3;
31	
32	/** Products the model may open in one `get_product_detail` call. */
33	export const MAX_DETAIL_SLUGS = 5;
34	
35	/** Tool round trips before we stop and answer with what we have. */
36	export const MAX_TOOL_ROUNDS = 4;
