38	/** Papers attached to a card. The sheet can fetch the rest. */
39	export const MAX_CITATIONS_PER_CARD = 3;
40	
41	export const RATE_LIMIT = { perHour: 15, perDay: 50 };
42	
43	const HOUR_MS = 60 * 60 * 1000;
44	const DAY_MS = 24 * HOUR_MS;
45	
46	// ============================================================================
47	// Wire types
48	// ============================================================================
49	
50	export type AskRole = 'user' | 'assistant';
51	
52	export interface AskTurn {
53	  role: AskRole;
54	  text: string;
55	}
56	
57	export interface AskRequest {
58	  question: string;
59	  history: AskTurn[];
60	}
61	
62	export type AskErrorCode = 'bad_request' | 'unauthorized' | 'rate_limited' | 'server_error';
63	
64	export interface AskErrorBody {
65	  error: { code: AskErrorCode; message: string; retry_after?: number };
66	}
67	
68	export interface AskCitation {
69	  title: string;
70	  meta: string | null;
71	  url: string | null;
72	}
73	
74	export interface AskCard {
75	  slug: string;
76	  name: string;
77	  brand: string | null;
78	  form: string | null;
79	  /** one line, the model's reason for this product for this person */
80	  reason: string;
81	  timing: string | null;
82	  timing_note: string | null;
83	  evidence: string | null;
84	  label_url: string | null;
