90	  remaining_day: number;
91	  resets_at: string;
92	}
93	
94	export interface AskAnswer {
95	  answer: string;
96	  cards: AskCard[];
97	  usage: AskUsage;
98	  /**
99	   * True when the wording came from `fixtures.ts` rather than the model —
100	   * either because no ANTHROPIC_API_KEY is set, or because the question was
101	   * refused by the scope gate before the model was called.
102	   */
103	  stub: boolean;
104	}
105	
106	/** One glossary row, trimmed to what the assistant is allowed to see. */
107	export interface CatalogueEntry {
108	  slug: string;
109	  name: string;
110	  brand: string | null;
111	  product_form: string | null;
112	  goal_tags: string[];
113	  kind: string | null;
114	  timing: string | null;
115	  timing_note: string | null;
116	  evidence: string | null;
117	  mechanism_summary: string | null;
118	  label_url: string | null;
119	  ods_url: string | null;
120	}
121	
122	/** What `show_products` asks for, after validation. */
123	export interface RequestedCard {
124	  slug: string;
125	  reason: string;
126	}
127	
128	export interface ToolSpec {
129	  name: string;
130	  description: string;
131	  input_schema: Record<string, unknown>;
132	}
