134	// ============================================================================
135	// Request validation
136	// ============================================================================
137	
138	export type Parsed<T> = { ok: true; value: T } | { ok: false; message: string };
139	
140	function asString(value: unknown): string | null {
141	  return typeof value === 'string' ? value : null;
142	}
143	
144	/**
145	 * Parses the POST body. Everything the client sends is treated as hostile:
146	 * the question is length-capped, the history is trimmed to the last
147	 * MAX_HISTORY_TURNS and anything that is not a plain user/assistant turn is
148	 * dropped rather than rejected, because a stale client should still get an
149	 * answer.
150	 */
151	export function parseRequest(raw: unknown): Parsed<AskRequest> {
152	  if (raw === null || typeof raw !== 'object') {
153	    return { ok: false, message: 'Send a JSON object with a question.' };
154	  }
155	  const body = raw as Record<string, unknown>;
156	  const question = (asString(body.question) ?? '').trim();
157	  if (!question) return { ok: false, message: 'Ask a question first.' };
158	  if (question.length > MAX_QUESTION_CHARS) {
159	    return { ok: false, message: `Questions are limited to ${MAX_QUESTION_CHARS} characters.` };
160	  }
161	
162	  const history: AskTurn[] = [];
163	  if (Array.isArray(body.history)) {
164	    for (const item of body.history) {
165	      if (item === null || typeof item !== 'object') continue;
166	      const turn = item as Record<string, unknown>;
167	      const role = asString(turn.role);
168	      const text = (asString(turn.text) ?? '').trim();
169	      if ((role !== 'user' && role !== 'assistant') || !text) continue;
170	      history.push({ role, text: text.slice(0, MAX_QUESTION_CHARS) });
171	    }
172	  }
173	
174	  return { ok: true, value: { question, history: history.slice(-MAX_HISTORY_TURNS) } };
175	}
176	
177	// ============================================================================
178	// Scope — what this assistant will not answer, decided before the model runs
179	// ============================================================================
180	
181	export type AskScope = 'ok' | 'peptide' | 'pregnancy';
182	
183	/**
184	 * Peptide names the app should recognise even when the catalogue does not hold
185	 * them. `index.ts` adds every `kind = 'peptide'` name and slug from the
186	 * glossary on top of this; the hardcoded list covers what people ask about but
187	 * the library has never listed.
188	 *
189	 * Deliberately no bare "peptide": the catalogue sells Vital Proteins Collagen
190	 * Peptides and a casein decapeptide, and refusing to talk about a product we
191	 * list would be worse than the thing this list is guarding against.
192	 */
193	export const PEPTIDE_TERMS = [
194	  'bpc-157', 'tb-500', 'tb4', 'thymosin beta-4', 'thymosin alpha-1',
195	  'cjc-1295', 'ipamorelin', 'sermorelin', 'tesamorelin', 'hexarelin',
196	  'ghrp-2', 'ghrp-6', 'ghrh', 'hgh', 'igf-1', 'igf-1 lr3', 'mk-677', 'ibutamoren',
197	  'semaglutide', 'tirzepatide', 'retatrutide', 'liraglutide', 'aod-9604',
198	  'ghk-cu', 'copper peptide', 'melanotan', 'pt-141', 'bremelanotide',
199	  'mots-c', 'humanin', 'ss-31', 'epitalon', 'pinealon', 'dsip', 'selank',
200	  'semax', 'kisspeptin', 'follistatin', 'thymulin', 'larazotide', 'p21',
201	  'cortexin', 'cerebrolysin', 'snap-8', 'matrixyl',
202	];
203	
204	/** Route words. The product has no injection UI anywhere, by design. */
205	const ROUTE_PATTERNS = [
206	  /\binject/,
207	  /\bsubcutaneous/,
208	  /\bintramuscular/,
209	  /\breconstitut/,
210	  /\bsyringe/,
211	  /\bbacteriostatic/,
212	];
213	
214	const PREGNANCY_TERMS = [
215	  'pregnant', 'pregnancy', 'breastfeeding', 'breast feeding', 'breastfeed',
216	  'lactating', 'lactation', 'trying to conceive', 'ttc', 'ivf',
217	  'trimester', 'postpartum', 'prenatal',
218	];
219	
220	/** lowercase, punctuation to single spaces, padded so `\b`-style tests are cheap */
221	function spaced(text: string): string {
222	  return ` ${text.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim()} `;
223	}
224	
225	function squashed(text: string): string {
226	  return text.toLowerCase().replace(/[^a-z0-9]+/g, '');
227	}
228	
229	function mentions(haystackSpaced: string, haystackSquashed: string, term: string): boolean {
230	  const normalised = spaced(term).trim();
231	  if (!normalised) return false;
232	  if (haystackSpaced.includes(` ${normalised} `)) return true;
233	  // "BPC157" and "TB500" are how people actually type them. Only terms that
234	  // carry a digit get the squashed pass — squashing a short word like "vip"
235	  // and matching it unanchored would fire on half the language.
236	  if (/\d/.test(normalised)) return haystackSquashed.includes(normalised.replace(/ /g, ''));
237	  return false;
238	}
239	
240	export function isPeptideQuestion(question: string, extraTerms: string[] = []): boolean {
241	  const hay = spaced(question);
242	  const squash = squashed(question);
243	  if (ROUTE_PATTERNS.some((re) => re.test(hay))) return true;
244	  for (const term of PEPTIDE_TERMS) if (mentions(hay, squash, term)) return true;
245	  for (const term of extraTerms) if (mentions(hay, squash, term)) return true;
246	  return false;
247	}
248	
249	export function isPregnancyQuestion(question: string): boolean {
250	  const hay = spaced(question);
251	  const squash = squashed(question);
252	  return PREGNANCY_TERMS.some((term) => mentions(hay, squash, term));
253	}
254	
255	/**
256	 * The server-side gate. It runs before the model does and cannot be talked out
257	 * of its answer, which is the entire reason it is here rather than in the
258	 * system prompt.
259	 *
260	 * Pregnancy is checked first: "is BPC-157 safe while pregnant" wants the
261	 * see-a-clinician answer more than it wants the we-don't-advise-on-peptides
262	 * one, and both decline.
263	 */
264	export function classifyScope(question: string, peptideTerms: string[] = []): AskScope {
265	  if (isPregnancyQuestion(question)) return 'pregnancy';
266	  if (isPeptideQuestion(question, peptideTerms)) return 'peptide';
267	  return 'ok';
268	}
