270	// ============================================================================
271	// Rate limiting
272	// ============================================================================
273	
274	export interface RateVerdict {
275	  allowed: boolean;
276	  remaining_hour: number;
277	  remaining_day: number;
278	  /** when the next slot frees up */
279	  resets_at: string;
280	  /** seconds; 0 when allowed */
281	  retry_after: number;
282	}
283	
284	/**
285	 * Given every call this user has made in the last day, decide whether this one
286	 * goes through. Both windows are rolling — a fixed hourly bucket lets someone
287	 * spend the whole allowance twice across a boundary.
288	 */
289	export function rateVerdict(nowMs: number, stampsMs: number[]): RateVerdict {
290	  const inDay = stampsMs.filter((t) => t > nowMs - DAY_MS).sort((a, b) => a - b);
291	  const inHour = inDay.filter((t) => t > nowMs - HOUR_MS);
292	
293	  const remaining_hour = Math.max(0, RATE_LIMIT.perHour - inHour.length);
294	  const remaining_day = Math.max(0, RATE_LIMIT.perDay - inDay.length);
295	  const allowed = remaining_hour > 0 && remaining_day > 0;
296	
297	  let resetMs: number;
298	  if (remaining_hour === 0 && inHour.length > 0) resetMs = inHour[0] + HOUR_MS;
299	  else if (remaining_day === 0 && inDay.length > 0) resetMs = inDay[0] + DAY_MS;
300	  else if (inHour.length > 0) resetMs = inHour[0] + HOUR_MS;
301	  else resetMs = nowMs + HOUR_MS;
302	
303	  return {
304	    allowed,
305	    remaining_hour,
306	    remaining_day,
307	    resets_at: new Date(resetMs).toISOString(),
308	    retry_after: allowed ? 0 : Math.max(1, Math.ceil((resetMs - nowMs) / 1000)),
309	  };
310	}
