354	export function catalogueLine(entry: CatalogueEntry): string {
355	  const goals = entry.goal_tags.length ? entry.goal_tags.join('/') : 'no goal';
356	  const form = entry.product_form ? `, ${entry.product_form}` : '';
357	  return `${entry.slug} | ${entry.name}${form} | ${goals}`;
358	}
