360	/**
361	 * The catalogue index. It is the same bytes for every person, so `index.ts`
362	 * puts the cache breakpoint on it and every request after the first reads it
363	 * back rather than paying for it again.
364	 */
365	export function buildCatalogueBlock(catalogue: CatalogueEntry[]): string {
366	  const lines = catalogue.map(catalogueLine);
367	  return [
368	    'CATALOGUE — slug | product | goals. Suggest nothing that is not on this list.',
369	    '',
370	    ...lines,
371	  ].join('\n');
372	}
373	
374	/** What `get_product_detail` hands back to the model. */
375	export function buildDetail(entry: CatalogueEntry, citations: AskCitation[]): string {
376	  const parts = [
377	    `${entry.slug} — ${entry.name}`,
378	    entry.brand ? `brand: ${entry.brand}` : null,
379	    entry.product_form ? `form: ${entry.product_form}` : null,
380	    entry.goal_tags.length ? `goals: ${entry.goal_tags.join(', ')}` : null,
381	    entry.mechanism_summary ? `what it is: ${entry.mechanism_summary}` : null,
382	    entry.timing ? `timing: ${entry.timing}` : null,
383	    entry.timing_note ? `timing note: ${entry.timing_note}` : null,
384	    entry.evidence ? `evidence: ${entry.evidence}` : 'evidence: not recorded',
385	  ].filter((line): line is string => line !== null);
386	
387	  if (citations.length) {
388	    parts.push('papers on file:');
389	    for (const c of citations) parts.push(`- ${c.title}${c.meta ? ` (${c.meta})` : ''}`);
390	  } else {
391	    parts.push('papers on file: none');
392	  }
393	  return parts.join('\n');
394	}
395	
396	export interface ProfileContext {
397	  age?: number | null;
398	  sex?: string | null;
399	  diet?: string[] | null;
400	  reactions?: string[] | null;
401	  reactions_note?: string | null;
402	  form_prefs?: string[] | null;
403	  wake_time?: string | null;
404	  sleep_time?: string | null;
405	}
406	
407	/**
408	 * The person, in one paragraph, carried in the user turn rather than the
409	 * system prompt — the system prompt is the cached prefix and must be identical
410	 * for everybody. Absent fields are simply left out; the model is told nothing
411	 * it was not given.
412	 */
413	export function buildProfileBlock(profile: ProfileContext | null, stackNames: string[]): string {
414	  if (!profile && stackNames.length === 0) return 'About them: nothing on file.';
415	  const bits: string[] = [];
416	  if (profile?.age) bits.push(`${profile.age} years old`);
417	  if (profile?.sex === 'm') bits.push('male');
418	  else if (profile?.sex === 'f') bits.push('female');
419	  if (profile?.diet?.length) bits.push(`diet: ${profile.diet.join(', ')}`);
420	  if (profile?.reactions?.length) bits.push(`has reacted badly to: ${profile.reactions.join(', ')}`);
421	  if (profile?.reactions_note) bits.push(`in their words: "${profile.reactions_note}"`);
422	  if (profile?.form_prefs?.length) bits.push(`prefers: ${profile.form_prefs.join(', ')}`);
423	  if (profile?.wake_time && profile?.sleep_time) {
424	    bits.push(`awake ${profile.wake_time.slice(0, 5)} to ${profile.sleep_time.slice(0, 5)}`);
425	  }
426	  if (stackNames.length) bits.push(`already taking: ${stackNames.join(', ')}`);
427	  return bits.length ? `About them: ${bits.join('; ')}.` : 'About them: nothing on file.';
428	}
429	
430	// ============================================================================
431	// Tools
432	// ============================================================================
433	
434	/**
435	 * Two tools, both of which read the database. The model picks slugs; the
436	 * server materialises everything the person actually sees, so a hallucinated
437	 * product cannot reach a card.
438	 *
439	 * Neither is `strict`: strict tool use rejects array constraints like
440	 * maxItems, and the limits are enforced in `readDetailSlugs` / `readShowProducts`
441	 * regardless of what the model sends.
442	 */
443	export const TOOLS: ToolSpec[] = [
444	  {
445	    name: 'get_product_detail',
446	    description:
447	      'Read the full library entry for up to five catalogue products: what the product is, when it is taken, how strong the evidence is, and the papers on file. Call this before answering anything about a specific product — the catalogue index in the system prompt carries only slugs, names and goals.',
448	    input_schema: {
449	      type: 'object',
450	      properties: {
451	        slugs: {
452	          type: 'array',
453	          items: { type: 'string' },
454	          maxItems: MAX_DETAIL_SLUGS,
455	          description: 'Catalogue slugs, exactly as they appear in the index.',
456	        },
457	      },
458	      required: ['slugs'],
459	      additionalProperties: false,
460	    },
461	  },
462	  {
463	    name: 'show_products',
464	    description:
465	      'Show product cards to the person, at most three, in the order they should read them. Every slug must come from the catalogue index; anything else is dropped and no card appears. Call this once, after any lookups. The card already shows the name, brand, form, timing and papers, so the reason should say why this one for this person and nothing else.',
466	    input_schema: {
467	      type: 'object',
468	      properties: {
469	        items: {
470	          type: 'array',
471	          maxItems: MAX_CARDS,
472	          items: {
473	            type: 'object',
474	            properties: {
475	              slug: { type: 'string', description: 'A slug from the catalogue index.' },
476	              reason: {
477	                type: 'string',
478	                description:
479	                  'One short sentence, under 120 characters, saying why this product for this person. No dose, no amount.',
480	              },
481	            },
482	            required: ['slug', 'reason'],
483	            additionalProperties: false,
484	          },
485	        },
486	      },
487	      required: ['items'],
488	      additionalProperties: false,
489	    },
490	  },
491	];
492	
493	export function readDetailSlugs(input: unknown): string[] {
494	  if (input === null || typeof input !== 'object') return [];
495	  const raw = (input as Record<string, unknown>).slugs;
496	  if (!Array.isArray(raw)) return [];
497	  const out: string[] = [];
498	  for (const item of raw) {
499	    const slug = asString(item)?.trim();
500	    if (slug && !out.includes(slug)) out.push(slug);
501	    if (out.length === MAX_DETAIL_SLUGS) break;
502	  }
503	  return out;
504	}
505	
506	export function readShowProducts(input: unknown): RequestedCard[] {
507	  if (input === null || typeof input !== 'object') return [];
508	  const raw = (input as Record<string, unknown>).items;
509	  if (!Array.isArray(raw)) return [];
510	  const out: RequestedCard[] = [];
511	  for (const item of raw) {
512	    if (item === null || typeof item !== 'object') continue;
513	    const row = item as Record<string, unknown>;
514	    const slug = asString(row.slug)?.trim();
515	    const reason = (asString(row.reason) ?? '').trim();
516	    if (!slug || out.some((c) => c.slug === slug)) continue;
517	    out.push({ slug, reason: reason.slice(0, 160) });
518	    if (out.length === MAX_CARDS) break;
519	  }
520	  return out;
521	}
522	
523	// ============================================================================
524	// Cards
525	// ============================================================================
526	
527	/**
528	 * Turns the slugs the model asked for into cards, using the database row for
529	 * every field the person sees. A slug the catalogue does not hold is dropped:
530	 * the alternative is rendering a product that does not exist.
531	 *
532	 * `fallback` is the stub path only — the fixtures name products from
533	 * migrations 0021 and 0022, which are written but not applied, so on a
534	 * database that has not had them run the fixture's own copy of the row stands
535	 * in rather than the answer arriving with no cards at all.
536	 */
537	export function buildCards(
538	  requested: RequestedCard[],
539	  catalogue: Map<string, CatalogueEntry>,
540	  citations: Map<string, AskCitation[]>,
541	  fallback?: Map<string, CatalogueEntry>,
542	): AskCard[] {
543	  const cards: AskCard[] = [];
544	  for (const item of requested.slice(0, MAX_CARDS)) {
545	    const entry = catalogue.get(item.slug) ?? fallback?.get(item.slug);
546	    if (!entry) continue;
547	    cards.push({
548	      slug: entry.slug,
549	      name: entry.name,
550	      brand: entry.brand,
551	      form: entry.product_form,
552	      reason: item.reason,
553	      timing: entry.timing,
554	      timing_note: entry.timing_note,
555	      evidence: entry.evidence,
556	      label_url: entry.label_url,
557	      citations: (citations.get(item.slug) ?? []).slice(0, MAX_CITATIONS_PER_CARD),
558	    });
559	  }
560	  return cards;
561	}
