}
.prod-btn.fill {
  background: var(--purple);
  color: var(--bg);
  box-shadow: none;
}
.prod-btn.fill:disabled {
  opacity: 0.65;
}
.prod-btn.wide {
  flex-basis: 100%;
}

/* ============================================================
   Ask AI
   ============================================================ */
.ask {
  display: flex;
  flex-direction: column;
  min-height: 62vh;
}
.ask-thread {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-top: 8px;
}
.ask-empty {
  text-align: center;
  padding: 30px 0 10px;
}
.ask-mark {
  display: inline-grid;
  place-items: center;
  width: 76px;
  height: 76px;
  border-radius: 24px;
  background: var(--card);
}
.ask-empty-line {
  margin: 16px auto 0;
  max-width: 260px;
  font-size: 16px;
  color: var(--t2);
  line-height: 1.5;
}
.ask-examples {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 22px;
}
.ask-example {
  min-height: 46px;
  padding: 12px 16px;
  border-radius: 16px;
  background: var(--card);
  color: var(--t2);
  font-size: 14px;
  text-align: left;
}
.ask-bubble {
  max-width: calc(100% - 60px);
  padding: 12px 15px;
  border-radius: 20px;
  font-size: 15px;
  line-height: 21px;
  letter-spacing: -0.1px;
  white-space: pre-wrap;
}
.ask-bubble.user {
  align-self: flex-end;
  background: var(--purple);
  color: #fff;
}
.ask-bubble.assistant {
  align-self: flex-start;
  background: var(--card);
  color: var(--t1);
}
.ask-dots {
  display: inline-flex;
  gap: 5px;
  padding: 3px 0;
}
.ask-dots i {
  width: 6px;
  height: 6px;
  border-radius: 3px;
  background: var(--t3);
  animation: ask-pulse 1.2s ease-in-out infinite;
}
.ask-dots i:nth-child(2) { animation-delay: 0.15s; }
.ask-dots i:nth-child(3) { animation-delay: 0.3s; }
@keyframes ask-pulse {
  0%, 60%, 100% { opacity: 0.3; }
  30% { opacity: 1; }
}
.ask-composer {
  position: sticky;
  bottom: 0;
  padding: 12px 0 4px;
  background: var(--bg);
}
.ask-input-row {
  display: flex;
  align-items: flex-end;
  gap: 8px;
}
.ask-input {
  flex: 1;
  min-width: 0;
  min-height: 48px;
  max-height: 132px;
  padding: 13px 16px;
  border-radius: 20px;
  border: 0;
  outline: none;
  resize: none;
  background: var(--card);
  color: var(--t1);
  font: inherit;
  font-size: 15px;
  line-height: 21px;
}
.ask-input::placeholder {
  color: var(--t3);
}
.ask-send {
  flex: none;
