115	    const single = wantsSingleObject(request);
116	    const matching = () => applyFilters(table, url.searchParams);
117	
118	    if (method === 'GET' || method === 'HEAD') {
119	      const rows = withLimit(matching(), url.searchParams);
120	      if (method === 'HEAD') {
121	        return route.fulfill({
122	          status: 200,
123	          contentType: 'application/json',
124	          headers: { 'content-range': `0-${Math.max(0, rows.length - 1)}/${rows.length}` },
125	          body: '',
126	        });
127	      }
