144	        // `now()` is a default on every table that carries the column.
145	        created_at: new Date().toISOString(),
146	        ...INSERT_DEFAULTS[relation],
147	        ...row,
148	      }));
149	      table.push(...incoming);
150	      if (single) return json(incoming[0] ?? null, 201);
151	      return json(incoming, 201);
152	    }
153	
154	    if (method === 'PATCH') {
155	      const patch = (request.postDataJSON() ?? {}) as Row;
156	      const hit = matching();
157	      for (const row of hit) Object.assign(row, patch);
158	      if (single) return json(hit[0] ?? null);
159	      return json(hit);
160	    }
