179	/** Everything in a PostgREST query string that is not a column filter. */
180	const RESERVED = new Set(['select', 'order', 'limit', 'offset', 'on_conflict', 'columns']);
181	
182	function applyFilters(rows: Row[], params: URLSearchParams): Row[] {
183	  let out = rows;
184	  for (const [column, raw] of params) {
185	    if (RESERVED.has(column)) continue;
186	    const eq = raw.match(/^eq\.(.*)$/s);
187	    if (eq) {
188	      out = out.filter((r) => String(r[column]) === eq[1]);
189	      continue;
190	    }
191	    const inList = raw.match(/^in\.\((.*)\)$/s);
192	    if (inList) {
193	      const wanted = new Set(inList[1].split(',').map((v) => v.replace(/^"|"$/g, '')));
194	      out = out.filter((r) => wanted.has(String(r[column])));
195	      continue;
196	    }
197	    const gte = raw.match(/^gte\.(.*)$/s);
198	    if (gte) {
199	      out = out.filter((r) => String(r[column]) >= gte[1]);
200	      continue;
201	    }
202	    const lte = raw.match(/^lte\.(.*)$/s);
203	    if (lte) {
204	      out = out.filter((r) => String(r[column]) <= lte[1]);
205	      continue;
206	    }
207	    // not./is./like. and the embedded-table filters fall through unfiltered.
208	  }
209	  return out;
210	}
211	
212	function withLimit(rows: Row[], params: URLSearchParams): Row[] {
213	  const limit = Number(params.get('limit'));
214	  return Number.isFinite(limit) && limit > 0 ? rows.slice(0, limit) : rows;
215	}
