69	const KEY = 'pepstack.onboarding.v1';
70	
71	/**
72	 * Persisted on every change rather than at the end. A backgrounded tab on iOS
73	 * can be discarded without warning, and losing eleven screens of answers is the
74	 * kind of thing people do not come back from.
75	 */
76	function load(): OnboardingState {
77	  try {
78	    const raw = localStorage.getItem(KEY);
79	    if (!raw) return initialState();
80	    const parsed = JSON.parse(raw) as Partial<OnboardingState>;
81	    // merge over defaults so a store written by an older build still opens
82	    const base = initialState();
83	    const merged: OnboardingState = {
84	      ...base,
85	      ...parsed,
86	      auth: { ...base.auth, ...parsed.auth },
87	      profile: { ...base.profile, ...parsed.profile },
88	      /* Named rather than spread, so a store written before q1 was cut does
89	         not carry its answer forward into a shape that no longer has it. */
90	      survey: { q2: parsed.survey?.q2 ?? null, q3: parsed.survey?.q3 ?? null },
91	      diet: Array.isArray(parsed.diet) ? parsed.diet : [],
92	      reactions: Array.isArray(parsed.reactions) ? parsed.reactions : [],
93	      reactionsNote: typeof parsed.reactionsNote === 'string' ? parsed.reactionsNote : '',
94	      forms: Array.isArray(parsed.forms) ? parsed.forms : [],
95	      meals: Array.isArray(parsed.meals) ? parsed.meals : base.meals,
96	      currentStack: Array.isArray(parsed.currentStack) ? parsed.currentStack : [],
97	      goals: Array.isArray(parsed.goals) ? parsed.goals : [],
98	      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations : [],
99	      schedule: Array.isArray(parsed.schedule) ? parsed.schedule : [],
100	    };
101	    // a step index from a longer or reordered FLOW must not land out of bounds
102	    merged.step = Math.max(0, Math.min(FLOW.length - 1, Number(merged.step) || 0));
103	    return merged;
104	  } catch {
105	    return initialState();
106	  }
107	}
