/** The answers that also live on `profiles`, in this file's shape. */
export interface PersistedAnswers {
  diet?: string[] | null;
  reactions?: string[] | null;
  reactionsNote?: string | null;
  forms?: string[] | null;
}

const KEY = 'pepstack.onboarding.v1';

/**
 * Persisted on every change rather than at the end. A backgrounded tab on iOS
 * can be discarded without warning, and losing eleven screens of answers is the
 * kind of thing people do not come back from.
 */
function load(): OnboardingState {
  try {
    const raw = localStorage.getItem(KEY);
    if (!raw) return initialState();
    const parsed = JSON.parse(raw) as Partial<OnboardingState>;
    // merge over defaults so a store written by an older build still opens
    const base = initialState();
    const merged: OnboardingState = {
      ...base,
      ...parsed,
      auth: { ...base.auth, ...parsed.auth },
      profile: { ...base.profile, ...parsed.profile },
      /* Named rather than spread, so a store written before q1 was cut does
         not carry its answer forward into a shape that no longer has it. */
      survey: { q2: parsed.survey?.q2 ?? null, q3: parsed.survey?.q3 ?? null },
      diet: Array.isArray(parsed.diet) ? parsed.diet : [],
      reactions: Array.isArray(parsed.reactions) ? parsed.reactions : [],
      reactionsNote: typeof parsed.reactionsNote === 'string' ? parsed.reactionsNote : '',
      forms: Array.isArray(parsed.forms) ? parsed.forms : [],
      meals: Array.isArray(parsed.meals) ? parsed.meals : base.meals,
      currentStack: Array.isArray(parsed.currentStack) ? parsed.currentStack : [],
      goals: Array.isArray(parsed.goals) ? parsed.goals : [],
      recommendations: Array.isArray(parsed.recommendations) ? parsed.recommendations : [],
      schedule: Array.isArray(parsed.schedule) ? parsed.schedule : [],
    };
    // a step index from a longer or reordered FLOW must not land out of bounds
    merged.step = Math.max(0, Math.min(FLOW.length - 1, Number(merged.step) || 0));
    return merged;
  } catch {
    return initialState();
  }
}

export function useOnboardingStore() {
  const [state, setState] = useState<OnboardingState>(load);

  useEffect(() => {
    try {
      localStorage.setItem(KEY, JSON.stringify(state));
    } catch {
      /* private mode, quota — losing persistence is survivable, crashing is not */
    }
  }, [state]);

  const patch = useCallback((p: Partial<OnboardingState>) => {
    setState((s) => ({ ...s, ...p }));
  }, []);

  /**
   * Fill in answers already on the profile row — a returning user on a new
   * device has nothing in localStorage and should not be asked twice. Only
   * fields still empty here are touched, so an answer given on this device
   * always wins over an older one coming back from the server.
   */

import { expect, test } from '@playwright/test';
import {
  buildCards,
  buildCatalogueBlock,
  buildProfileBlock,
  classifyScope,
  isPeptideQuestion,
  isPregnancyQuestion,
  MAX_CARDS,
  MAX_HISTORY_TURNS,
  MAX_QUESTION_CHARS,
  parseRequest,
  RATE_LIMIT,
  rateVerdict,
  readDetailSlugs,
  readShowProducts,
  TOOLS,
} from '../../supabase/functions/ask/lib';
import type { AskCitation, CatalogueEntry } from '../../supabase/functions/ask/lib';
import { ANSWER_FIXTURES, pickFixture, STUB_TRIGGERS } from '../../supabase/functions/ask/fixtures';

/**
 * The half of the ask function that can be wrong quietly.
 *
 * The edge function itself needs Deno, a database and a key, and none of the
 * three exist here — so everything that decides *what the answer is allowed to
 * be* lives in `lib.ts` and is tested in Node, next to the rule tables. The
 * two that matter most are the scope gate (a peptide question must never reach
 * the model) and card resolution (a slug the catalogue does not hold must
 * never reach a card).
 */

const HOUR = 60 * 60 * 1000;

const entry = (over: Partial<CatalogueEntry> & { slug: string }): CatalogueEntry => ({
  name: over.slug,
  brand: null,
  product_form: null,
  goal_tags: [],
  kind: 'supplement',
  timing: null,
  timing_note: null,
  evidence: null,
  mechanism_summary: null,
  label_url: null,
  ods_url: null,
  ...over,
});

// ============================================================================
// Request parsing
// ============================================================================

test('a question is required', () => {
  expect(parseRequest({ question: '   ' }).ok).toBe(false);
  expect(parseRequest({}).ok).toBe(false);
  expect(parseRequest(null).ok).toBe(false);
  expect(parseRequest('what is zinc').ok).toBe(false);
});

