import { expect, seedSignedIn, test } from './support/app';

/** Temporary: screenshots for a visual check. Deleted before commit. */
test('shots', async ({ page, app }) => {
  await seedSignedIn(page, app.stub);
  app.allowConsoleError(/status of 429/);
  await page.goto('/');
  await expect(page.getByRole('heading', { name: 'Today' })).toBeVisible();
  await page.getByRole('button', { name: 'Discover', exact: true }).click();
  await page.getByRole('tab', { name: 'Ask AI' }).click();
  const panel = page.locator('.tabs-panel').first();

  await page.screenshot({ path: 'test-results/shot-empty.png' });

  await panel.getByRole('button', { name: 'What should I take for hair thinning?' }).click();
  await expect(panel.locator('.ask-card')).toHaveCount(3);
  await page.screenshot({ path: 'test-results/shot-answer.png', fullPage: true });

  await panel.locator('.ask-card').first().getByRole('button', { name: '2 papers' }).click();
  await expect(page.locator('.sheet')).toBeVisible();
  await page.waitForTimeout(500);
  await page.screenshot({ path: 'test-results/shot-sheet.png' });
  await page.locator('.sheet').getByRole('button', { name: 'Close' }).click();

  await panel.getByPlaceholder('Ask a question').fill('test rate limit');
  await panel.getByRole('button', { name: 'Send' }).click();
  await expect(panel.locator('.ask-notice')).toBeVisible();
  await page.screenshot({ path: 'test-results/shot-error.png', fullPage: true });

  await panel.getByPlaceholder('Ask a question').fill(
    'A much longer question that will wrap over several lines in the composer so that the five line cap can be seen working the way it is supposed to, growing and then scrolling instead.',
  );
  await page.screenshot({ path: 'test-results/shot-input.png' });
});

